  $sections$[{"type":"anuncio","mensaje":"Envíos a todo el país · 3 cuotas sin interés · Retiro en el local sin cargo"},{"type":"header","variant":"clasico"},{"type":"hero","variant":"destacado","titulo":"Un libro para cada quien que entra.","descripcion":"Cuarenta y siete años recomendando lecturas. Si no lo tenemos, lo buscamos y te avisamos cuando llega.","heroImagen":"https://d38e2ri338t20n.cloudfront.net/uploads/8f8606b5-2297-4e26-8cbb-02484fd15ea3.jpg","destacadoEtiqueta":"Lo de esta semana","destacado":{"imagen":"https://d38e2ri338t20n.cloudfront.net/uploads/3a2ccdfd-b2c9-4181-a560-2be8205c98c4.jpg","titulo":"Las malas","autor":"Camila Sosa Villada","precio":"$24.100","disponibilidad":"En stock"},"botones":{"primary":{"funcion":"seccion","label":"Buscar en el catálogo"},"secondary":{"funcion":"seccion","label":"Club de lectura"}}},{"type":"catalogo-libros","eyebrow":"Catálogo","titulo":"Buscá tu próxima lectura","items":[{"id":"libro-1","titulo":"Los siete locos","autor":"Roberto Arlt","genero":"Clásicos argentinos","precio":"$18.900","stock":"En stock","stockColor":"#3f6b6b","img":"https://d38e2ri338t20n.cloudfront.net/uploads/c4cd761f-cb16-45b3-8f4d-eaee74182e13.jpg"},{"id":"libro-2","titulo":"Cometierra","autor":"Dolores Reyes","genero":"Narrativa contemporánea","precio":"$22.400","stock":"Últimos 3","stockColor":"#b4472b","img":"https://d38e2ri338t20n.cloudfront.net/uploads/a616eafb-cfdb-4593-a2b2-4c822b76eaae.jpg"},{"id":"libro-3","titulo":"El invencible verano de Liliana","autor":"Cristina Rivera Garza","genero":"No ficción","precio":"$27.800","stock":"Últimos 1","stockColor":"#b4472b","img":"https://d38e2ri338t20n.cloudfront.net/uploads/32116e15-97a1-439e-94ff-4d4f9c995e37.jpg"},{"id":"libro-4","titulo":"Las malas","autor":"Camila Sosa Villada","genero":"Narrativa contemporánea","precio":"$24.100","stock":"En stock","stockColor":"#3f6b6b","img":"https://d38e2ri338t20n.cloudfront.net/uploads/3a2ccdfd-b2c9-4181-a560-2be8205c98c4.jpg"},{"id":"libro-5","titulo":"Cuentos de la selva","autor":"Horacio Quiroga","genero":"Infantil y juvenil","precio":"$12.600","stock":"En stock","stockColor":"#3f6b6b","img":"https://d38e2ri338t20n.cloudfront.net/uploads/e02fc10e-17c1-44fe-80e3-1823d6f72118.jpg"},{"id":"libro-6","titulo":"Breve historia del tiempo","autor":"Stephen Hawking","genero":"Divulgación","precio":"$26.300","stock":"En stock","stockColor":"#3f6b6b","img":"https://d38e2ri338t20n.cloudfront.net/uploads/b06fab86-79c0-45a6-9a0a-3a644e734fd6.jpg"},{"id":"libro-7","titulo":"Ficciones","autor":"Jorge Luis Borges","genero":"Clásicos argentinos","precio":"$19.700","stock":"En stock","stockColor":"#3f6b6b","img":"https://d38e2ri338t20n.cloudfront.net/uploads/ae1cb075-d411-4b87-a1bc-cbc79dd15b0b.jpg"},{"id":"libro-8","titulo":"La uruguaya","autor":"Pedro Mairal","genero":"Narrativa contemporánea","precio":"$17.200","stock":"A pedido","stockColor":"#9c9384","img":"https://d38e2ri338t20n.cloudfront.net/uploads/c80529b1-19d3-4036-b610-ec120f33f6c9.jpg"},{"id":"libro-9","titulo":"Manual de dibujo para chicos","autor":"Varios autores","genero":"Infantil y juvenil","precio":"$14.900","stock":"En stock","stockColor":"#3f6b6b","img":"https://d38e2ri338t20n.cloudfront.net/uploads/ca3a1a23-5e63-44bd-b62f-0f0184c9e957.jpg"},{"id":"libro-10","titulo":"Sapiens","autor":"Yuval Noah Harari","genero":"Divulgación","precio":"$31.500","stock":"Últimos 2","stockColor":"#b4472b","img":"https://d38e2ri338t20n.cloudfront.net/uploads/89b3a851-19a4-4760-9ff9-1b26fd9de0af.jpg"}]},{"type":"recomendados","eyebrow":"El staff recomienda","titulo":"Lo que estamos leyendo","descripcion":"Cada ficha la escribió quien lo leyó. Preguntanos en el local y te contamos más.","items":[{"id":"pick-1","titulo":"Cometierra","autor":"Dolores Reyes","staff":"Mariela, atención al público","nota":"Lo empecé un martes y no lo pude soltar. La voz de la narradora te queda dando vueltas días después. Si te gustó Mariana Enriquez, este es el próximo.","img":"https://d38e2ri338t20n.cloudfront.net/uploads/cb4ce170-b358-4c48-adf6-3bca44333c21.jpg"},{"id":"pick-2","titulo":"El invencible verano de Liliana","autor":"Cristina Rivera Garza","staff":"Andrés, encargado","nota":"Difícil y necesario. Lo recomiendo con la advertencia de leerlo despacio. Uno de los mejores libros de no ficción que pasaron por acá.","img":"https://d38e2ri338t20n.cloudfront.net/uploads/ab2e5219-a922-4329-adaa-275ffbea8b30.jpg"},{"id":"pick-3","titulo":"Cuentos de la selva","autor":"Horacio Quiroga","staff":"Paula, sección infantil","nota":"Se lo leo a los chicos en los talleres del sábado y siempre funciona. Edición nueva con ilustraciones hermosas.","img":"https://d38e2ri338t20n.cloudfront.net/uploads/ed9f3c31-0f1f-4cc4-b54f-a55adb2c5e59.jpg"}]},{"type":"club-lectura","bgColor":"#1d2b2f","textColor":"#f4efe4","eyebrow":"Club de lectura · Edición 112","titulo":"Este mes leemos Los siete locos","descripcion":"Nos juntamos el tercer jueves de cada mes a discutir el libro elegido. No hace falta haberlo terminado ni saber de literatura: solo venir con ganas de charlar.","imagen":"https://d38e2ri338t20n.cloudfront.net/uploads/f8961b67-2766-46f7-ae27-dbd442856f0a.jpg","datos":[{"id":"dato-1","label":"Próximo encuentro","valor":"Jueves 21 de agosto, 19 hs"},{"id":"dato-2","label":"Dónde","valor":"Entrepiso de la librería"},{"id":"dato-3","label":"Cuánto","valor":"Gratis · 15% off en el libro"}],"etiquetaSinUnir":"Anotarme al encuentro","etiquetaUnido":"✓ Estás anotado","notaSinUnir":"Quedan 8 lugares de 24","notaUnido":"Quedan 7 lugares · te esperamos"},{"type":"firmas-eventos","titulo":"Firmas y presentaciones","nota":"Entrada libre · Se sugiere reservar","items":[{"id":"evt-1","dia":"08","mes":"Ago","titulo":"Presentación: \"Ruido de fondo\"","detalle":"Con la autora Lucía Bertoldi y lectura de fragmentos.","hora":"19:00"},{"id":"evt-2","dia":"15","mes":"Ago","titulo":"Firma de ejemplares · Pedro Mairal","detalle":"Traé tu ejemplar o compralo en el local ese día.","hora":"18:30"},{"id":"evt-3","dia":"22","mes":"Ago","titulo":"Taller de lectura para chicos","detalle":"De 6 a 10 años. Cupo limitado a 15 chicos.","hora":"11:00"},{"id":"evt-4","dia":"29","mes":"Ago","titulo":"Mesa redonda: traducir poesía","detalle":"Con traductores de tres editoriales independientes.","hora":"19:30"}]},{"type":"pedidos-especiales","eyebrow":"Pedidos especiales","titulo":"Si no lo tenemos, lo conseguimos","descripcion":"Trabajamos con más de 40 editoriales y hacemos importaciones cada quince días. Sin anticipo: pagás cuando llega.","pasos":[{"id":"paso-1","texto":"Nos dejás el título y tu WhatsApp."},{"id":"paso-2","texto":"Consultamos disponibilidad y te pasamos precio en 24 hs."},{"id":"paso-3","texto":"Si aceptás, lo pedimos: llega entre 3 y 15 días según editorial."}],"mensajeConfirmado":"Anotamos \"{titulo}\". Te escribimos por WhatsApp en menos de 24 hs con precio y fecha estimada de llegada."},{"type":"testimonios","variant":"scroll"},{"type":"visitanos-boletin","eyebrowContacto":"Visitanos","filas":[{"id":"fila-1","label":"Dirección","valor":"Honduras 4250, Palermo, CABA"},{"id":"fila-2","label":"Horarios","valor":"Lun a Sáb 10 a 20:30 · Dom 14 a 20 hs"},{"id":"fila-3","label":"Teléfono","valor":"011 4832-7710"}],"eyebrowBoletin":"Boletín de novedades","descripcionBoletin":"Una vez al mes: novedades, el libro del club y los eventos que vienen.","mensajeSuscripto":"Anotado. Te escribimos el primer lunes del mes."},{"type":"footer","variant":"minimal"}]$sections$::jsonb,
